/// The Postgres schemas whose `outbox_events` table this module's staged events are written to.
pub const OUTBOX_SCHEMAS: &[&str] = &["bucket"];

/// Create the outbox and inbox tables of [`OUTBOX_SCHEMAS`] (idempotent). The composing service
/// runs it at startup with a role that may create tables, beside its relay; a write that stages an
/// event needs the table to exist.
pub async fn migrate_outbox(pool: &backbone_orm::PgPool) -> anyhow::Result<()> {
    for schema in OUTBOX_SCHEMAS {
        backbone_core::write_hooks::migrate_outbox(pool, schema).await?;
    }
    Ok(())
}
